<?php
add_filter('pre_wp_mail',function($r,$a){update_option('pelham_qa_mail',$a);return true;},10,2);
add_action('wp_ajax_pelham_qa_offer',function(){if(!current_user_can('manage_options'))wp_die('',403);wp_send_json(['release'=>get_option('pelham_offer_release'),'mail'=>get_option('pelham_qa_mail'),'levels'=>pelham_ltl_levels()]);});
add_action('wp_ajax_pelham_qa_reset',function(){if(!current_user_can('manage_options'))wp_die('',403);global $wpdb;$wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE 'pelham_enquiry_lock_%' OR option_name LIKE '_transient_pelham_rate_%' OR option_name LIKE '_transient_timeout_pelham_rate_%'");wp_send_json_success();});
add_action('wp_ajax_pelham_qa_reapply',function(){if(!current_user_can('manage_options'))wp_die('',403);$result=pelham_apply_offer();$checks=[];foreach(pelham_offer_entries() as $e){$p=$e['route']==='home'?get_post((int)get_option('page_on_front')):get_posts(['post_type'=>$e['type'],'name'=>basename($e['route']),'numberposts'=>1])[0];$checks[$e['route']]=['backup'=>(bool)get_post_meta($p->ID,'pelham_before_offer_1_9',true),'matches'=>pelham_18_signature($p->post_content)===pelham_18_signature($e['content'])];}wp_send_json(['result'=>!is_wp_error($result),'checks'=>$checks]);});
if(($_SERVER['HTTP_X_PELHAM_QA_PRODUCTION']??'')==='local-seo-test'){add_filter('pre_option_home',fn()=> 'https://pelhamservices.com');add_filter('pre_option_blog_public',fn()=>1);add_filter('redirect_canonical','__return_false');}
add_action('wp_ajax_pelham_qa_seo',function(){if(!current_user_can('manage_options'))wp_die('',403);update_option('pelham_legacy_redirects',true);$r=pelham_apply_offer();$q=apply_filters('wp_sitemaps_posts_query_args',[],'page');wp_send_json(['updated'=>!is_wp_error($r),'private'=>$q['post__not_in'],'authors'=>apply_filters('wp_sitemaps_add_provider',(object)[],'users'),'bad'=>pelham_legacy_destination(['page_id'=>['10']],'/'),'unknown'=>pelham_legacy_destination(['page_id'=>'99999'],'/'),'conflict'=>pelham_legacy_destination(['page_id'=>'10','p'=>'1'],'/')]);});
add_action('wp_ajax_pelham_qa_seo_patch',function(){if(!current_user_can('manage_options'))wp_die('',403);$id=get_page_by_path('register')->ID;$saved=get_post_meta($id,'pelham_seo_description',true);$old='Download Pelham registration forms and submit customer onboarding documents.';update_post_meta($id,'pelham_seo_description',$old);do_action('admin_init');$new=get_post_meta($id,'pelham_seo_description',true);update_post_meta($id,'pelham_seo_description','Custom registration description');do_action('admin_init');$custom=get_post_meta($id,'pelham_seo_description',true);update_post_meta($id,'pelham_seo_description',$new);wp_send_json(['new'=>$new,'custom'=>$custom,'backup'=>get_post_meta($id,'pelham_seo_description_before_1_10_1',true),'blocks'=>pelham_robots_root_blocks("User-agent: Googlebot\nDisallow: /\nUser-agent: *\nAllow: /"),'allow'=>pelham_robots_root_blocks("User-agent: *\nDisallow: /wp-admin/\nAllow: /wp-admin/admin-ajax.php")]);});
